<?php
/** Fetch the current Yoast sitemap only via an explicitly configured internal origin. */
function r1_sitemap_local_path($url,$public){$p=parse_url($url);if(!is_array($p)||!in_array($p['scheme']??'',['http','https'],true)||strcasecmp((string)($p['host']??''),$public)!==0||isset($p['user'])||isset($p['pass'])||isset($p['fragment']))throw new InvalidArgumentException('unexpected sitemap URL');$path=$p['path']??'/';if(!preg_match('~^/(?!/)[^\r\n]*$~',$path)||strpos($path,'..')!==false)throw new InvalidArgumentException('unsafe sitemap path');return $path.(isset($p['query'])?'?'.$p['query']:'');}
if(defined('R1_SITEMAP_LIST_TEST_ONLY')&&R1_SITEMAP_LIST_TEST_ONLY)return;
if(PHP_SAPI!=='cli'||$argc!==2||file_exists($argv[1])){fwrite(STDERR,"usage: php r1-sitemap-list.php NEW.json\n");exit(2);}
try{
 $origin=getenv('R1_AUDIT_ORIGIN')?:'http://packrivo-r1-proxy';$host=getenv('R1_AUDIT_HOST')?:'www.packrivo.com';$public=getenv('R1_PUBLIC_HOST')?:'www.packrivo.com';$o=parse_url($origin);
 if(!is_array($o)||!in_array($o['scheme']??'',['http','https'],true)||empty($o['host'])||isset($o['user'])||isset($o['pass'])||!empty($o['path'])||isset($o['query'])||isset($o['fragment'])||!preg_match('/^[A-Za-z0-9.:-]+$/D',$host)||!preg_match('/^[A-Za-z0-9.-]+$/D',$public))throw new InvalidArgumentException('invalid audit origin or host');
 $fetch=static function($path)use($origin,$host){$c=curl_init($origin.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_TIMEOUT=>90,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_PROXY=>'',CURLOPT_HTTPHEADER=>['Host: '.$host]]);$v=curl_exec($c);$code=(int)curl_getinfo($c,CURLINFO_RESPONSE_CODE);$error=curl_error($c);curl_close($c);if($code!==200||!is_string($v))throw new RuntimeException('sitemap HTTP '.$code.' '.$path.' '.$error);return $v;};
 $parse=static function($data){$previous=libxml_use_internal_errors(true);$xml=simplexml_load_string($data,'SimpleXMLElement',LIBXML_NONET|LIBXML_NOERROR|LIBXML_NOWARNING);libxml_clear_errors();libxml_use_internal_errors($previous);if(!$xml)throw new RuntimeException('invalid sitemap XML');$xml->registerXPathNamespace('s','http://www.sitemaps.org/schemas/sitemap/0.9');return $xml;};
 $index=$parse($fetch('/sitemap_index.xml'));$children=$index->xpath('//s:sitemap/s:loc')?:[];if(!$children)throw new RuntimeException('empty sitemap index');$paths=[];
 foreach($children as $loc){$child=r1_sitemap_local_path((string)$loc,$public);$xml=$parse($fetch($child));foreach($xml->xpath('//s:url/s:loc')?:[] as $u){$path=r1_sitemap_local_path((string)$u,$public);if(isset($paths[$path]))throw new RuntimeException('duplicate sitemap path '.$path);$paths[$path]=true;}}
 if(!$paths)throw new RuntimeException('empty sitemap');$list=array_keys($paths);sort($list,SORT_STRING);$data=json_encode($list,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$f=fopen($argv[1],'x');if(!$f||fwrite($f,$data)!==strlen($data)||!fclose($f))throw new RuntimeException('cannot write sitemap list');echo 'SITEMAP_PATHS='.count($list)."\n";
}catch(Throwable $e){fwrite(STDERR,'SITEMAP_STOP '.$e->getMessage()."\n");exit(1);}
